do $conteudo$
declare
  v_doc jsonb := $doc$[{"circuito":"rodillas","exercicios":[{"dia":1,"ordem":1,"ordem_circuito":1,"nome":"Péndulo de pierna","descricao":"Día 1 — Despertar suave y circulación","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada en el borde de una silla firme, espalda larga, manos apoyadas a los lados del asiento. Una pierna cuelga libre.\nMovimiento: Deja que la pierna se balancee hacia adelante y atrás con suavidad, como un péndulo. El pie apenas roza el aire, sin patear.\nRespiración: Respira tranquila por la nariz, sin seguir un ritmo fijo.\nQué vas a sentir: Una sensación de soltura y de espacio dentro de la rodilla.\nAtención: El movimiento es pequeño y relajado; si algo molesta, reduce el balanceo.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Sentada un poco más alta, sobre un cojín firme encima de la silla, para que la pierna cuelgue más libre.\nMovimiento: Balancea la pierna con un recorrido un poco mayor y más lento. Al final de cada vaivén, deja que la pierna se detenga sola antes de volver.\nRespiración: Suelta el aire cuando la pierna va hacia adelante, inspira cuando vuelve.\nQué vas a sentir: La rodilla ligera, como si el peso del pie le diera un poco de espacio.\nAtención: No fuerces la pierna a estirarse del todo; deja que el peso haga el trabajo.","duracao_seg":null}]},{"dia":1,"ordem":2,"ordem_circuito":2,"nome":"Deslizar el talón","descricao":"Día 1 — Despertar suave y circulación","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba en el suelo o la cama, piernas estiradas. Puedes poner un calcetín para que el talón deslice mejor.\nMovimiento: Desliza un talón hacia el glúteo, doblando la rodilla despacio. Luego estira la pierna de nuevo, sin levantar el pie.\nRespiración: Inspira al doblar, suelta el aire al estirar.\nQué vas a sentir: La rodilla doblándose y estirándose con suavidad, cada vez un poco más fluida.\nAtención: Muévete solo dentro del rango sin dolor; no busques doblar al máximo.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Igual que antes, boca arriba, con una toalla pequeña doblada bajo el talón para que deslice con facilidad.\nMovimiento: Desliza el talón más despacio, contando cuatro tiempos al doblar y cuatro al estirar. Al final, deja la pierna larga un instante.\nRespiración: Respiración lenta y larga que acompaña todo el recorrido.\nQué vas a sentir: Un movimiento más controlado y una sensación de calor suave en la rodilla.\nAtención: Mantén la rodilla apuntando al techo, sin que caiga hacia adentro o hacia afuera.","duracao_seg":null}]},{"dia":1,"ordem":3,"ordem_circuito":3,"nome":"Bombeo de tobillos","descricao":"Día 1 — Despertar suave y circulación","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, piernas estiradas y relajadas, brazos a los lados del cuerpo.\nMovimiento: Lleva las puntas de los pies hacia ti y luego empújalas lejos, como pisando un pedal. Ambos pies a la vez, a ritmo tranquilo.\nRespiración: Respira con naturalidad, sin contener el aire.\nQué vas a sentir: Las pantorrillas trabajando y una sensación de circulación que despierta las piernas.\nAtención: Si sientes un calambre, afloja el movimiento y estira la pantorrilla con calma.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Acostada boca arriba, con los pies apoyados sobre un cojín para que queden un poco elevados.\nMovimiento: Haz el mismo bombeo, pero más amplio y más lento, llevando las puntas bien hacia ti y bien lejos.\nRespiración: Inspira al traer las puntas, suelta el aire al empujarlas.\nQué vas a sentir: Las piernas más ligeras y despiertas, desde los pies hasta las rodillas.\nAtención: Mantén las rodillas relajadas; el movimiento nace solo de los tobillos.","duracao_seg":null}]},{"dia":1,"ordem":4,"ordem_circuito":4,"nome":"Rodilla al pecho con alivio","descricao":"Día 1 — Despertar suave y circulación","tipo":"permanencia","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas y pies apoyados. Toma una rodilla con las manos por detrás del muslo.\nMovimiento: Acerca la rodilla al pecho hasta un punto cómodo y quédate ahí. Deja que la pierna pese en tus manos.\nRespiración: Respira lento y, en cada salida del aire, suelta un poco más la pierna.\nQué vas a sentir: Una sensación de alivio en la cadera y de espacio alrededor de la rodilla.\nAtención: Sostén por detrás del muslo, no sobre la rodilla, para no apretarla.","duracao_seg":25},{"nivel":2,"instrucoes":"Preparación: Acostada boca arriba, con la otra pierna estirada en el suelo o la cama.\nMovimiento: Lleva la rodilla al pecho y sostenla. Durante la pausa, haz pequeños círculos lentos con el tobillo de esa pierna.\nRespiración: Respiración profunda y tranquila durante toda la pausa.\nQué vas a sentir: La cadera abierta y la rodilla suelta, sin presión.\nAtención: Si la pierna estirada tira de la espalda, vuelve a doblarla.","duracao_seg":40}]},{"dia":1,"ordem":5,"ordem_circuito":5,"nome":"Pedaleo suave acostada","descricao":"Día 1 — Despertar suave y circulación","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas y pies apoyados. Brazos relajados a los lados.\nMovimiento: Desliza un pie por el suelo estirando la pierna y vuelve; luego la otra, como un pedaleo lento que no despega del suelo.\nRespiración: Respira con calma siguiendo el ritmo de las piernas.\nQué vas a sentir: Las piernas moviéndose ligeras y la rodilla lubricada con cada vuelta.\nAtención: Mantén la espalda apoyada y tranquila; el ritmo es lento.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Acostada boca arriba, con ambos pies un poco levantados del suelo y las rodillas dobladas.\nMovimiento: Pedalea en el aire con círculos pequeños y lentos, como en una bicicleta muy tranquila.\nRespiración: Suelta el aire en cada vuelta completa, sin apurarte.\nQué vas a sentir: Calor suave en los muslos y rodillas que se mueven con fluidez.\nAtención: Si la zona lumbar se arquea, apoya un pie y pedalea con una pierna a la vez.","duracao_seg":null}]},{"dia":2,"ordem":1,"ordem_circuito":6,"nome":"Masaje alrededor de la rótula","descricao":"Día 2 — Rótula libre y flexión cómoda","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada en el suelo o la cama, con una pierna estirada y totalmente relajada. El muslo suelto, sin apretar.\nMovimiento: Con la yema de los dedos, mueve la rótula muy suave hacia arriba y abajo, y luego de lado a lado. Movimientos pequeños y lentos.\nRespiración: Respira tranquila y deja el muslo blando.\nQué vas a sentir: La rótula deslizándose con más facilidad y una sensación de soltura.\nAtención: Es un toque delicado; si la zona está sensible, reduce la presión.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Igual que antes, con una toalla enrollada bajo la rodilla para que quede apenas doblada y relajada.\nMovimiento: Mueve la rótula en las cuatro direcciones y luego haz pequeños círculos lentos a su alrededor con los dedos.\nRespiración: Suelta el aire largo mientras masajeas, sin prisa.\nQué vas a sentir: Calor agradable alrededor de la rodilla y la sensación de que se afloja.\nAtención: Nunca empujes la rótula con fuerza; solo guíala.","duracao_seg":null}]},{"dia":2,"ordem":2,"ordem_circuito":7,"nome":"Flexión asistida con toalla","descricao":"Día 2 — Rótula libre y flexión cómoda","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, con una toalla pasada por debajo de la planta de un pie. Sostén las puntas con las manos.\nMovimiento: Usa la toalla para acercar el talón hacia el glúteo, doblando la rodilla. Luego deja que la pierna vuelva a estirarse despacio.\nRespiración: Inspira al doblar, suelta el aire al estirar.\nQué vas a sentir: La toalla te ayuda y la rodilla se dobla sin esfuerzo.\nAtención: Tira con suavidad y detente antes de cualquier molestia.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Acostada boca arriba, toalla bajo el pie, la otra pierna estirada.\nMovimiento: Dobla la rodilla con ayuda de la toalla y, al llegar al punto cómodo, sostén dos respiraciones antes de volver despacio.\nRespiración: Dos respiraciones lentas en la pausa, luego suelta al estirar.\nQué vas a sentir: Un poco más de recorrido cómodo que en la semana anterior.\nAtención: La rodilla sigue la línea del pie; no la dejes caer hacia un lado.","duracao_seg":null}]},{"dia":2,"ordem":3,"ordem_circuito":8,"nome":"Extensión sentada lenta","descricao":"Día 2 — Rótula libre y flexión cómoda","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada en una silla firme, espalda apoyada, pies en el suelo al ancho de la cadera.\nMovimiento: Estira una rodilla levantando el pie hasta donde sea cómodo y bájalo despacio. No hace falta estirar del todo.\nRespiración: Suelta el aire al subir el pie, inspira al bajarlo.\nQué vas a sentir: El muslo trabajando suave y la rodilla moviéndose con fluidez.\nAtención: Evita dejar caer el pie de golpe; bájalo con control.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Sentada en la silla, con las manos sobre los muslos y la espalda larga, sin apoyarte en el respaldo.\nMovimiento: Estira la rodilla contando tres tiempos, haz una pequeña pausa arriba y baja en tres tiempos.\nRespiración: Suelta el aire en la subida y en la pausa, inspira al bajar.\nQué vas a sentir: El muslo más activo y la rodilla estable en todo el recorrido.\nAtención: Si la rodilla chasquea sin dolor, sigue suave; si duele, reduce el recorrido.","duracao_seg":null}]},{"dia":2,"ordem":4,"ordem_circuito":9,"nome":"Limpiaparabrisas de rodillas","descricao":"Día 2 — Rótula libre y flexión cómoda","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas y pies apoyados un poco más separados que la cadera.\nMovimiento: Deja caer ambas rodillas suavemente hacia un lado y vuelve al centro; luego hacia el otro lado. Recorrido pequeño.\nRespiración: Suelta el aire al llevar las rodillas al lado, inspira al volver.\nQué vas a sentir: Las caderas y rodillas soltándose con un balanceo agradable.\nAtención: Los hombros quedan apoyados; no fuerces las rodillas hacia el suelo.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Igual que antes, con los brazos abiertos en cruz para dar más apoyo.\nMovimiento: Lleva las rodillas hacia un lado más despacio y un poco más lejos, sostén una respiración y vuelve al centro.\nRespiración: Una respiración completa en cada lado, sin apurarte.\nQué vas a sentir: Un estiramiento suave en la cadera y los lados de los muslos.\nAtención: Muévete solo hasta donde las rodillas bajen sin molestia.","duracao_seg":null}]},{"dia":2,"ordem":5,"ordem_circuito":10,"nome":"Talón al glúteo boca abajo","descricao":"Día 2 — Rótula libre y flexión cómoda","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca abajo en la cama o sobre una manta, frente apoyada sobre las manos. Un cojín bajo el vientre si lo necesitas.\nMovimiento: Dobla una rodilla llevando el talón hacia el glúteo, hasta donde sea cómodo, y bájalo despacio.\nRespiración: Suelta el aire al doblar, inspira al bajar.\nQué vas a sentir: La parte de atrás del muslo trabajando y la rodilla doblándose libre.\nAtención: Si la posición boca abajo molesta la espalda, hazlo de pie, apoyada en una silla.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Boca abajo, igual que antes, con una toalla pequeña doblada bajo la rodilla que trabaja.\nMovimiento: Dobla la rodilla más lento, en cuatro tiempos, y baja también en cuatro, sin dejar caer el pie.\nRespiración: Respiración lenta y continua durante todo el movimiento.\nQué vas a sentir: Más control y un recorrido cómodo un poco mayor.\nAtención: La cadera queda apoyada; no la levantes para ganar recorrido.","duracao_seg":null}]},{"dia":3,"ordem":1,"ordem_circuito":11,"nome":"Rodilla que aprieta la toalla","descricao":"Día 3 — Muslos que sostienen","tipo":"permanencia","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada en el suelo o la cama, piernas estiradas, con una toalla enrollada bajo una rodilla.\nMovimiento: Aprieta la parte de atrás de la rodilla contra la toalla activando el muslo, y mantén. Las puntas del pie miran al techo.\nRespiración: Respira con normalidad; no contengas el aire mientras sostienes.\nQué vas a sentir: El músculo de adelante del muslo firme y la rótula subiendo un poquito.\nAtención: La fuerza es moderada; si aparece dolor detrás de la rodilla, afloja.","duracao_seg":20},{"nivel":2,"instrucoes":"Preparación: Igual que antes, con la toalla un poco menos enrollada para que la rodilla quede casi estirada.\nMovimiento: Aprieta la toalla y, al mismo tiempo, lleva las puntas del pie hacia ti. Sostén con el muslo activo.\nRespiración: Respiración tranquila y constante durante toda la pausa.\nQué vas a sentir: Todo el muslo despierto y la pierna firme como un tronco.\nAtención: Suelta despacio al terminar, sin relajar de golpe.","duracao_seg":35}]},{"dia":3,"ordem":2,"ordem_circuito":12,"nome":"Pierna recta al cielo","descricao":"Día 3 — Muslos que sostienen","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, una rodilla doblada con el pie apoyado y la otra pierna estirada.\nMovimiento: Activa el muslo de la pierna estirada y levántala hasta la altura de la otra rodilla. Baja despacio.\nRespiración: Suelta el aire al subir, inspira al bajar.\nQué vas a sentir: El muslo trabajando y la rodilla firme, sin doblarse.\nAtención: Mantén la zona lumbar apoyada; si se arquea, sube menos.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Igual que antes, boca arriba, con una rodilla doblada y la otra pierna estirada.\nMovimiento: Sube la pierna en tres tiempos, sostén un instante arriba y baja en tres tiempos, sin apoyar del todo antes de repetir.\nRespiración: Suelta el aire en la subida y en la pausa, inspira al bajar.\nQué vas a sentir: Más trabajo en el muslo y la sensación de una pierna fuerte y estable.\nAtención: Si la rodilla se dobla al subir, reduce la altura.","duracao_seg":null}]},{"dia":3,"ordem":3,"ordem_circuito":13,"nome":"Cojín entre las rodillas","descricao":"Día 3 — Muslos que sostienen","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada en una silla, pies apoyados, con un cojín entre las rodillas.\nMovimiento: Aprieta el cojín con suavidad durante tres segundos y suelta. Repite a ritmo tranquilo.\nRespiración: Suelta el aire al apretar, inspira al soltar.\nQué vas a sentir: La parte interna de los muslos activa, dando apoyo a las rodillas.\nAtención: Aprieta con fuerza moderada, sin tensar hombros ni mandíbula.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Sentada al borde de la silla, sin apoyar la espalda, cojín entre las rodillas.\nMovimiento: Aprieta el cojín y, sin soltarlo, estira un poco las dos rodillas levantando apenas los pies. Baja y suelta.\nRespiración: Suelta el aire al apretar y subir, inspira al volver.\nQué vas a sentir: Muslos trabajando juntos y rodillas alineadas.\nAtención: Levanta solo unos centímetros; la espalda se mantiene larga.","duracao_seg":null}]},{"dia":3,"ordem":4,"ordem_circuito":14,"nome":"Arco corto con toalla","descricao":"Día 3 — Muslos que sostienen","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada o semisentada, con una toalla bien enrollada o un cojín bajo una rodilla.\nMovimiento: Sin despegar la rodilla del apoyo, levanta el talón estirando la pierna. Baja despacio.\nRespiración: Suelta el aire al estirar, inspira al bajar.\nQué vas a sentir: El músculo de adelante del muslo, justo encima de la rodilla, trabajando.\nAtención: El recorrido es corto; no hace falta estirar del todo si molesta.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Igual que antes, con el apoyo bajo la rodilla un poco más alto.\nMovimiento: Estira la pierna, sostén tres segundos con el muslo firme y baja en tres tiempos.\nRespiración: Respira durante la pausa, sin contener el aire.\nQué vas a sentir: Un trabajo más intenso encima de la rodilla, controlado y seguro.\nAtención: Mantén las puntas del pie mirando al techo durante todo el movimiento.","duracao_seg":null}]},{"dia":3,"ordem":5,"ordem_circuito":15,"nome":"Pierna estirada en la silla","descricao":"Día 3 — Muslos que sostienen","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada en una silla firme, con la espalda apoyada. Estira una pierna adelante con el talón en el suelo.\nMovimiento: Con la rodilla estirada, levanta el pie unos centímetros del suelo y bájalo despacio.\nRespiración: Suelta el aire al subir, inspira al bajar.\nQué vas a sentir: Todo el muslo trabajando y la pierna ligera.\nAtención: Si sientes tensión en la espalda, apóyate bien en el respaldo.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Sentada un poco más adelante en la silla, manos a los lados del asiento, pierna estirada.\nMovimiento: Levanta el pie, haz dos pequeños movimientos arriba y abajo sin tocar el suelo, y baja despacio.\nRespiración: Respira con naturalidad durante los pequeños movimientos.\nQué vas a sentir: Un calor sano en el muslo y más confianza en la pierna.\nAtención: Mantén la rodilla estirada sin bloquearla con fuerza.","duracao_seg":null}]},{"dia":4,"ordem":1,"ordem_circuito":16,"nome":"Puente suave","descricao":"Día 4 — Caderas y glúteos que protegen","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas, pies apoyados al ancho de la cadera y brazos a los lados.\nMovimiento: Aprieta los glúteos y eleva la cadera solo unos centímetros. Baja despacio, vértebra por vértebra.\nRespiración: Suelta el aire al subir, inspira al bajar.\nQué vas a sentir: Los glúteos trabajando y las rodillas estables, sin presión.\nAtención: Las rodillas apuntan hacia adelante, en línea con el segundo dedo del pie.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Igual que antes, con un cojín entre las rodillas.\nMovimiento: Aprieta el cojín, eleva la cadera un poco más alto, sostén dos respiraciones y baja despacio.\nRespiración: Dos respiraciones tranquilas arriba, luego suelta al bajar.\nQué vas a sentir: Glúteos y muslos trabajando juntos, dando soporte a las rodillas.\nAtención: No arquees la espalda; la subida viene de los glúteos.","duracao_seg":null}]},{"dia":4,"ordem":2,"ordem_circuito":17,"nome":"Almeja de lado","descricao":"Día 4 — Caderas y glúteos que protegen","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada de lado, rodillas dobladas y juntas, cabeza apoyada en el brazo o en un cojín.\nMovimiento: Manteniendo los pies juntos, abre la rodilla de arriba como una almeja y ciérrala despacio.\nRespiración: Suelta el aire al abrir, inspira al cerrar.\nQué vas a sentir: El costado del glúteo trabajando, cerca de la cadera.\nAtención: La cadera no rueda hacia atrás; abre solo lo que puedas sin girar el cuerpo.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Igual que antes, acostada de lado, con la mano de arriba apoyada en la cadera para sentirla quieta.\nMovimiento: Abre la rodilla, sostén dos segundos arriba y cierra en tres tiempos.\nRespiración: Respira con calma en la pausa, sin contener el aire.\nQué vas a sentir: Un trabajo más profundo en el glúteo lateral.\nAtención: Si molesta la rodilla de abajo, pon un cojín entre las rodillas y el suelo.","duracao_seg":null}]},{"dia":4,"ordem":3,"ordem_circuito":18,"nome":"Elevación lateral acostada","descricao":"Día 4 — Caderas y glúteos que protegen","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada de lado, la pierna de abajo doblada para dar apoyo y la de arriba estirada.\nMovimiento: Levanta la pierna de arriba un palmo, con el pie paralelo al suelo, y bájala despacio.\nRespiración: Suelta el aire al subir, inspira al bajar.\nQué vas a sentir: El costado de la cadera trabajando.\nAtención: No lleves la pierna hacia adelante; mantenla en línea con el cuerpo.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Igual que antes, de lado, con la pierna de arriba estirada y el cuerpo largo.\nMovimiento: Sube la pierna en tres tiempos, sostén un instante y baja en tres tiempos, sin apoyarla del todo.\nRespiración: Respiración constante, sin apurar la bajada.\nQué vas a sentir: Más trabajo en la cadera y una pierna que se mueve con control.\nAtención: Sube solo hasta donde la cadera no se inclina hacia atrás.","duracao_seg":null}]},{"dia":4,"ordem":4,"ordem_circuito":19,"nome":"Patada atrás con silla","descricao":"Día 4 — Caderas y glúteos que protegen","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie detrás de una silla firme, manos en el respaldo, rodillas suaves.\nMovimiento: Lleva una pierna estirada hacia atrás unos centímetros, apretando el glúteo, y vuelve despacio.\nRespiración: Suelta el aire al llevar la pierna atrás, inspira al volver.\nQué vas a sentir: El glúteo trabajando y la rodilla de apoyo firme.\nAtención: No inclines el tronco hacia adelante; el movimiento es pequeño.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: De pie detrás de la silla, con solo las yemas de los dedos en el respaldo.\nMovimiento: Lleva la pierna atrás, sostén dos segundos y vuelve en tres tiempos, sin apoyar el pie entre repeticiones.\nRespiración: Respira con calma durante la pausa.\nQué vas a sentir: Glúteo más activo y más equilibrio en la pierna de apoyo.\nAtención: Mantén la rodilla de apoyo levemente flexionada, sin bloquear.","duracao_seg":null}]},{"dia":4,"ordem":5,"ordem_circuito":20,"nome":"Apertura lateral de pie","descricao":"Día 4 — Caderas y glúteos que protegen","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie al lado de una silla, una mano en el respaldo, pies juntos.\nMovimiento: Lleva una pierna estirada hacia el lado unos centímetros y vuelve despacio a juntar los pies.\nRespiración: Suelta el aire al abrir, inspira al cerrar.\nQué vas a sentir: El costado de la cadera trabajando y la rodilla de apoyo estable.\nAtención: El cuerpo queda recto; no te inclines hacia el lado contrario.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: De pie al lado de la silla, apenas con la punta de los dedos en el respaldo.\nMovimiento: Abre la pierna, sostén dos segundos y vuelve en tres tiempos sin apoyar el pie.\nRespiración: Respiración tranquila durante todo el movimiento.\nQué vas a sentir: Cadera fuerte y más estabilidad en la pierna de apoyo.\nAtención: Las puntas del pie miran hacia adelante, no hacia arriba.","duracao_seg":null}]},{"dia":5,"ordem":1,"ordem_circuito":21,"nome":"Círculos de tobillo","descricao":"Día 5 — Pantorrillas, tobillos y equilibrio","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada en una silla, espalda apoyada. Levanta un pie apenas del suelo, sosteniendo el muslo con las manos si lo necesitas.\nMovimiento: Dibuja círculos lentos con el tobillo, primero en un sentido y luego en el otro.\nRespiración: Respira con naturalidad, sin prisa.\nQué vas a sentir: El tobillo soltándose y la pantorrilla despertando.\nAtención: Solo se mueve el tobillo; la rodilla queda quieta.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Sentada, con la pierna estirada adelante y el talón apoyado en el suelo.\nMovimiento: Dibuja círculos más amplios y más lentos, como si escribieras con los dedos del pie.\nRespiración: Suelta el aire largo en cada vuelta.\nQué vas a sentir: Todo el tobillo y la pantorrilla más móviles.\nAtención: Si aparece un calambre, apoya el pie y descansa un momento.","duracao_seg":null}]},{"dia":5,"ordem":2,"ordem_circuito":22,"nome":"Subir a las puntas","descricao":"Día 5 — Pantorrillas, tobillos y equilibrio","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie detrás de una silla firme, manos en el respaldo, pies al ancho de la cadera.\nMovimiento: Sube despacio a las puntas de los pies y baja los talones con control.\nRespiración: Suelta el aire al subir, inspira al bajar.\nQué vas a sentir: Las pantorrillas trabajando y los tobillos firmes.\nAtención: El peso va sobre el dedo gordo y el segundo dedo, sin que el tobillo se vaya hacia afuera.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: De pie detrás de la silla, apenas con la punta de los dedos en el respaldo.\nMovimiento: Sube a las puntas en dos tiempos, sostén un instante y baja en cuatro tiempos.\nRespiración: Respiración tranquila, sin contener el aire arriba.\nQué vas a sentir: Pantorrillas más fuertes y más control en la bajada.\nAtención: Las rodillas quedan suaves, sin bloquearlas hacia atrás.","duracao_seg":null}]},{"dia":5,"ordem":3,"ordem_circuito":23,"nome":"Balanceo talón y punta","descricao":"Día 5 — Pantorrillas, tobillos y equilibrio","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie detrás de una silla, manos en el respaldo, pies paralelos.\nMovimiento: Pasa el peso hacia las puntas y luego hacia los talones, levantando apenas las puntas. Un balanceo suave, adelante y atrás.\nRespiración: Respira con calma siguiendo el balanceo.\nQué vas a sentir: Tobillos trabajando y el cuerpo buscando su centro.\nAtención: Movimiento pequeño; las manos quedan listas en el respaldo.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: De pie al lado de la silla, una sola mano apoyada.\nMovimiento: Haz el balanceo más lento, sosteniendo un segundo en las puntas y un segundo en los talones.\nRespiración: Suelta el aire en cada cambio de apoyo.\nQué vas a sentir: Más equilibrio y los pies más despiertos.\nAtención: Si pierdes el equilibrio, vuelve a apoyar las dos manos.","duracao_seg":null}]},{"dia":5,"ordem":4,"ordem_circuito":24,"nome":"Equilibrio en un pie","descricao":"Día 5 — Pantorrillas, tobillos y equilibrio","tipo":"permanencia","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie al lado de una silla firme, una mano en el respaldo, mirada al frente.\nMovimiento: Levanta un pie apenas del suelo y quédate en equilibrio sobre la otra pierna, con la rodilla suave.\nRespiración: Respira lento y tranquilo, sin contener el aire.\nQué vas a sentir: El pie de apoyo haciendo pequeños ajustes y la rodilla estable.\nAtención: Si te desequilibras, apoya el pie; la silla siempre queda al alcance.","duracao_seg":20},{"nivel":2,"instrucoes":"Preparación: De pie al lado de la silla, solo con la punta de los dedos en el respaldo o con la mano cerca, sin tocar.\nMovimiento: Levanta el pie un poco más, con la rodilla doblada al frente, y sostén el equilibrio.\nRespiración: Respiración lenta; fija la mirada en un punto adelante.\nQué vas a sentir: Más confianza en la pierna de apoyo.\nAtención: La rodilla de apoyo queda alineada con el segundo dedo del pie, sin irse hacia adentro.","duracao_seg":35}]},{"dia":5,"ordem":5,"ordem_circuito":25,"nome":"Pantorrilla larga en la pared","descricao":"Día 5 — Pantorrillas, tobillos y equilibrio","tipo":"permanencia","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie frente a la pared, manos apoyadas a la altura del pecho. Una pierna adelante con la rodilla suave, la otra atrás.\nMovimiento: Con el talón de atrás en el suelo, inclina el cuerpo apenas hacia la pared hasta sentir la pantorrilla. Quédate ahí.\nRespiración: Respira profundo y suelta un poco más en cada salida del aire.\nQué vas a sentir: Un estiramiento agradable en la pantorrilla de la pierna de atrás.\nAtención: El pie de atrás apunta hacia la pared, no hacia afuera.","duracao_seg":25},{"nivel":2,"instrucoes":"Preparación: Igual que antes, con la pierna de atrás un paso más lejos de la pared.\nMovimiento: Inclina el cuerpo hacia la pared y, a mitad de la pausa, dobla un poquito la rodilla de atrás sin levantar el talón.\nRespiración: Respiración lenta y larga durante toda la pausa.\nQué vas a sentir: El estiramiento bajando de la pantorrilla hacia el tobillo.\nAtención: Estira hasta una tensión suave, nunca hasta el dolor.","duracao_seg":40}]},{"dia":6,"ordem":1,"ordem_circuito":26,"nome":"Sentarse y levantarse","descricao":"Día 6 — Fuerza amable para el día a día","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada al borde de una silla firme apoyada contra la pared, pies al ancho de la cadera, manos en los muslos.\nMovimiento: Inclina el tronco adelante y levántate empujando el suelo con los pies. Vuelve a sentarte despacio, sin dejarte caer.\nRespiración: Suelta el aire al levantarte, inspira al sentarte.\nQué vas a sentir: Muslos y glúteos trabajando juntos, como en el día a día.\nAtención: Las rodillas siguen la línea del segundo dedo del pie; puedes usar las manos en los muslos para ayudarte.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Sentada al borde de la silla, brazos cruzados sobre el pecho.\nMovimiento: Levántate sin usar las manos y siéntate en cuatro tiempos, rozando apenas el asiento antes de volver a subir.\nRespiración: Suelta el aire al subir, inspira durante la bajada lenta.\nQué vas a sentir: Más fuerza y control, y confianza al levantarte.\nAtención: Si cuesta sin manos, apóyalas en los muslos; lo importante es la bajada lenta.","duracao_seg":null}]},{"dia":6,"ordem":2,"ordem_circuito":27,"nome":"Sentadilla corta en la pared","descricao":"Día 6 — Fuerza amable para el día a día","tipo":"permanencia","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie con la espalda apoyada en la pared, pies un paso adelante y al ancho de la cadera.\nMovimiento: Desliza la espalda por la pared doblando apenas las rodillas, como si fueras a sentarte muy alto, y quédate ahí.\nRespiración: Respira con calma, sin contener el aire.\nQué vas a sentir: Los muslos trabajando de forma firme y tranquila.\nAtención: Baja muy poco: las rodillas nunca pasan de la punta de los pies. Sube si sientes dolor.","duracao_seg":20},{"nivel":2,"instrucoes":"Preparación: Igual que antes, espalda en la pared, con un cojín entre las rodillas.\nMovimiento: Baja un poco más que la semana anterior, siempre en una flexión cómoda, aprieta el cojín y sostén.\nRespiración: Respiración constante durante toda la pausa.\nQué vas a sentir: Muslos firmes y rodillas bien alineadas.\nAtención: No bajes más allá de un ángulo cómodo; es una sentadilla corta, nunca profunda.","duracao_seg":30}]},{"dia":6,"ordem":3,"ordem_circuito":28,"nome":"Toque de escalón","descricao":"Día 6 — Fuerza amable para el día a día","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie al lado de una silla, una mano en el respaldo, pies juntos.\nMovimiento: Levanta un pie como si subieras un escalón bajo, toca el suelo adelante con la punta y vuelve.\nRespiración: Respira con naturalidad, a ritmo tranquilo.\nQué vas a sentir: La cadera y el muslo levantando la pierna y la rodilla de apoyo estable.\nAtención: Sin saltos ni golpes; el pie toca el suelo con suavidad.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: De pie al lado de la silla, apenas con la punta de los dedos en el respaldo.\nMovimiento: Levanta la rodilla un poco más alto, toca adelante con la punta y vuelve despacio, pasando por arriba otra vez.\nRespiración: Suelta el aire al subir la rodilla, inspira al volver.\nQué vas a sentir: Más control y la sensación de subir escaleras con confianza.\nAtención: La rodilla de apoyo queda suave y alineada con el pie.","duracao_seg":null}]},{"dia":6,"ordem":4,"ordem_circuito":29,"nome":"Marcha lenta con silla","descricao":"Día 6 — Fuerza amable para el día a día","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie detrás de una silla firme, manos en el respaldo, espalda larga.\nMovimiento: Marcha en el lugar levantando una rodilla y luego la otra, despacio y a una altura cómoda.\nRespiración: Respira con calma siguiendo el ritmo de los pasos.\nQué vas a sentir: Las piernas activas y la circulación despierta.\nAtención: Apoya el pie con suavidad, sin golpear el suelo.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: De pie al lado de la silla, una sola mano en el respaldo.\nMovimiento: Marcha más lento, sosteniendo la rodilla arriba un segundo antes de apoyar el pie.\nRespiración: Suelta el aire al subir cada rodilla.\nQué vas a sentir: Más equilibrio en cada paso y rodillas que se mueven con control.\nAtención: Mantén el tronco erguido; no te inclines hacia atrás al subir la rodilla.","duracao_seg":null}]},{"dia":6,"ordem":5,"ordem_circuito":30,"nome":"Paso lateral suave","descricao":"Día 6 — Fuerza amable para el día a día","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie, pies juntos, rodillas levemente dobladas. Puedes tener una pared o una silla cerca.\nMovimiento: Da un paso al lado, junta el otro pie y vuelve hacia el otro lado. Pasos cortos y tranquilos.\nRespiración: Respira con naturalidad durante todo el movimiento.\nQué vas a sentir: Los costados de la cadera trabajando y las rodillas estables.\nAtención: Las puntas de los pies miran siempre hacia adelante.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: De pie, con las rodillas un poco más dobladas y las manos en la cintura.\nMovimiento: Da pasos laterales un poco más largos manteniendo la misma altura, sin subir ni bajar entre pasos.\nRespiración: Respiración constante, sin contener el aire.\nQué vas a sentir: Glúteos y muslos trabajando juntos, con más confianza al moverte.\nAtención: La flexión es pequeña; si molesta, estira un poco más las rodillas.","duracao_seg":null}]},{"dia":7,"ordem":1,"ordem_circuito":31,"nome":"Mini flexión con puntas","descricao":"Día 7 — Integración y descanso","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie detrás de una silla, manos en el respaldo, pies al ancho de la cadera.\nMovimiento: Dobla apenas las rodillas, vuelve a estirarlas y sube a las puntas. Baja los talones y repite en una sola ola.\nRespiración: Inspira al doblar, suelta el aire al subir a las puntas.\nQué vas a sentir: Tobillos, rodillas y caderas moviéndose juntos, en armonía.\nAtención: La flexión es pequeña y las rodillas siguen la línea de los pies.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: De pie detrás de la silla, apenas con la punta de los dedos en el respaldo.\nMovimiento: Haz la misma ola más lenta, sosteniendo un instante en las puntas antes de bajar.\nRespiración: Respiración larga que acompaña todo el movimiento.\nQué vas a sentir: Piernas coordinadas y más seguridad en el apoyo.\nAtención: Si pierdes el equilibrio arriba, sube menos a las puntas.","duracao_seg":null}]},{"dia":7,"ordem":2,"ordem_circuito":32,"nome":"Péndulo de pie","descricao":"Día 7 — Integración y descanso","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie al lado de una silla, una mano en el respaldo. Si puedes, párate sobre un cojín firme o un libro grueso con la pierna de apoyo, para que la otra cuelgue libre.\nMovimiento: Balancea la pierna libre hacia adelante y atrás, suelta y relajada, con un recorrido pequeño.\nRespiración: Respira tranquila, sin seguir un ritmo fijo.\nQué vas a sentir: La rodilla suelta y la cadera moviéndose sin esfuerzo.\nAtención: Es un balanceo suave, no una patada.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Igual que antes, con la mano apenas apoyada en el respaldo.\nMovimiento: Balancea con un recorrido un poco mayor y más lento, dejando que la pierna se detenga sola en cada extremo.\nRespiración: Suelta el aire cuando la pierna va hacia adelante.\nQué vas a sentir: La pierna ligera y una sensación de espacio en la articulación.\nAtención: La pierna de apoyo queda suave y firme; si te cansas, cambia de lado.","duracao_seg":null}]},{"dia":7,"ordem":3,"ordem_circuito":33,"nome":"Mecerse con las rodillas","descricao":"Día 7 — Integración y descanso","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, lleva las dos rodillas hacia el pecho y sostenlas con las manos por detrás de los muslos.\nMovimiento: Mécete suavemente de un lado al otro, como una cuna, con un movimiento pequeño.\nRespiración: Respira lento y deja que el cuerpo se afloje.\nQué vas a sentir: Un masaje suave en la espalda y alivio en caderas y rodillas.\nAtención: Si llevar las dos rodillas molesta, hazlo con una pierna y la otra apoyada.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Igual que antes, rodillas al pecho, manos por detrás de los muslos.\nMovimiento: Mécete de lado a lado y luego haz pequeños círculos con las rodillas juntas, despacio.\nRespiración: Suelta el aire largo en cada vuelta.\nQué vas a sentir: Todo el cuerpo relajado y las rodillas con más espacio.\nAtención: Sostén siempre por detrás de los muslos, no sobre las rodillas.","duracao_seg":null}]},{"dia":7,"ordem":4,"ordem_circuito":34,"nome":"Pierna al cielo con toalla","descricao":"Día 7 — Integración y descanso","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas. Pasa una toalla por la planta de un pie y sostén las puntas.\nMovimiento: Con ayuda de la toalla, estira la pierna hacia el techo hasta un punto cómodo y vuelve a doblarla despacio.\nRespiración: Suelta el aire al estirar, inspira al doblar.\nQué vas a sentir: Un estiramiento suave detrás del muslo y la rodilla estirándose con facilidad.\nAtención: No hace falta estirar del todo; basta con una tensión leve.","duracao_seg":null},{"nivel":2,"instrucoes":"Preparación: Boca arriba, con la otra pierna estirada en el suelo y la toalla bajo el pie que trabaja.\nMovimiento: Estira la pierna hacia el techo, sostén dos respiraciones y, en la pausa, lleva las puntas del pie hacia ti. Vuelve despacio.\nRespiración: Dos respiraciones lentas en la pausa.\nQué vas a sentir: El estiramiento de toda la parte de atrás de la pierna, sin tirones.\nAtención: Si la espalda se levanta, dobla la pierna que está en el suelo.","duracao_seg":null}]},{"dia":7,"ordem":5,"ordem_circuito":35,"nome":"Piernas en descanso","descricao":"Día 7 — Integración y descanso","tipo":"permanencia","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, con las pantorrillas apoyadas sobre el asiento de una silla o sobre cojines altos. Brazos relajados.\nMovimiento: Quédate quieta y deja que las piernas descansen por completo. Suelta el peso de las rodillas.\nRespiración: Inspira por la nariz y suelta el aire lento por la boca.\nQué vas a sentir: Piernas ligeras y una sensación de alivio y calma en las rodillas.\nAtención: Si sientes hormigueo, acerca un poco la cadera o baja la altura del apoyo.","duracao_seg":30},{"nivel":2,"instrucoes":"Preparación: Igual que antes, con las pantorrillas sobre la silla y una toalla doblada bajo la cabeza.\nMovimiento: Descansa y, en cada salida del aire, imagina que las rodillas se aflojan y ganan espacio. Al final, mueve los dedos de los pies despacio.\nRespiración: Respiración lenta, con la salida del aire más larga que la entrada.\nQué vas a sentir: Todo el cuerpo tranquilo y las piernas livianas.\nAtención: Al terminar, gira de lado y levántate con calma, sin prisa.","duracao_seg":45}]}],"alongamentos":[{"ordem":1,"nome":"Péndulo sentada","descricao":"Sentada en el borde de una silla, deja una pierna colgar suelta. Balancéala hacia adelante y atrás con suavidad, sin esfuerzo, como un péndulo.","lados":2},{"ordem":2,"nome":"Tobillos que dibujan","descricao":"Sentada, levanta un pie apenas del suelo y dibuja círculos lentos con el tobillo. Cambia de dirección a la mitad del tiempo.","lados":2},{"ordem":3,"nome":"Talón que se desliza","descricao":"Acostada boca arriba, desliza un talón por el suelo o la cama hacia el glúteo y vuelve a estirar la pierna. Solo hasta donde se sienta cómodo.","lados":2},{"ordem":4,"nome":"Rodilla al pecho","descricao":"Acostada boca arriba, abraza una rodilla y acércala al pecho con suavidad. Respira tranquila y deja que la cadera se afloje.","lados":2},{"ordem":5,"nome":"Círculos de cadera","descricao":"De pie, con las manos en el respaldo de una silla, haz círculos amplios y lentos con la cadera. Las rodillas quedan suaves, sin bloquear.","lados":1},{"ordem":6,"nome":"Muslo de atrás con toalla","descricao":"Acostada, pasa una toalla por la planta de un pie y sube la pierna hasta sentir un estiramiento leve detrás del muslo. La otra rodilla queda doblada.","lados":2},{"ordem":7,"nome":"Pantorrilla en la pared","descricao":"De pie frente a la pared, apoya las manos y lleva una pierna atrás con el talón en el suelo. Inclina el cuerpo apenas hacia la pared hasta sentir la pantorrilla.","lados":2},{"ordem":8,"nome":"Balanceo de peso","descricao":"De pie, pies al ancho de la cadera, pasa el peso de un pie al otro despacio. Siente cómo cada rodilla recibe y suelta el peso con calma.","lados":1}]},{"circuito":"cadera","exercicios":[{"dia":1,"ordem":1,"ordem_circuito":1,"nome":"Respiración con pelvis suelta","descricao":"Día 1 — Soltar y despertar la circulación","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas y pies apoyados al ancho de la cadera. Manos sobre el vientre.\nMovimiento: Al soltar el aire, deja que la pelvis se incline apenas hacia atrás. Al inspirar, vuelve a la posición natural. Todo muy pequeño.\nRespiración: Inspira por la nariz en 4 tiempos y suelta por la boca en 6.\nQué vas a sentir: La parte baja del cuerpo aflojándose con cada respiración.\nAtención: Si algo molesta, haz el movimiento todavía más pequeño o solo respira.","duracao_seg":null}]},{"dia":1,"ordem":2,"ordem_circuito":2,"nome":"Pies que caminan acostada","descricao":"Día 1 — Soltar y despertar la circulación","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas y pies apoyados en el suelo o la cama.\nMovimiento: Desliza un pie hacia adelante hasta estirar la pierna y vuelve. Alterna los lados con ritmo tranquilo, como si caminaras despacio.\nRespiración: Respira libre, sin retener el aire.\nQué vas a sentir: La cadera y la ingle moviéndose con suavidad y un poco de calor en las piernas.\nAtención: Mantén la espalda relajada sobre el suelo; si se arquea, estira menos la pierna.","duracao_seg":null}]},{"dia":1,"ordem":3,"ordem_circuito":3,"nome":"Rodillas que se mecen","descricao":"Día 1 — Soltar y despertar la circulación","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas y juntas, pies apoyados.\nMovimiento: Mece las rodillas unos centímetros hacia un lado y hacia el otro, como un péndulo pequeño. Los hombros quedan tranquilos en el suelo.\nRespiración: Suelta el aire al ir hacia un lado, inspira al volver al centro.\nQué vas a sentir: Un masaje suave en la cadera y en la parte baja de la espalda.\nAtención: Mueve solo hasta donde se sienta cómodo, sin dolor.","duracao_seg":null}]},{"dia":1,"ordem":4,"ordem_circuito":4,"nome":"Descanso con piernas en alto","descricao":"Día 1 — Soltar y despertar la circulación","tipo":"permanencia","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, con las pantorrillas apoyadas sobre el asiento de una silla o sobre cojines.\nMovimiento: Quédate quieta y deja que el peso de las piernas descanse por completo. Solo observa cómo se afloja la cadera.\nRespiración: Respiración lenta y natural, llevando el aire hacia el vientre.\nQué vas a sentir: Las piernas livianas y la cadera descansando.\nAtención: Si sientes hormigueo, baja un poco las piernas o cambia de posición.","duracao_seg":40}]},{"dia":2,"ordem":1,"ordem_circuito":5,"nome":"Círculos de rodilla acostada","descricao":"Día 2 — Movilidad suave de la cadera","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba. Lleva una rodilla hacia el pecho y apoya la mano sobre ella.\nMovimiento: Dibuja círculos pequeños con la rodilla, como si revolvieras una olla. Cambia de dirección a la mitad del tiempo y luego de pierna.\nRespiración: Respira tranquila, sin retener el aire.\nQué vas a sentir: La articulación de la cadera girando con suavidad.\nAtención: Haz círculos pequeños; si hay molestia aguda, detente.","duracao_seg":null}]},{"dia":2,"ordem":2,"ordem_circuito":6,"nome":"Talón al glúteo de pie","descricao":"Día 2 — Movilidad suave de la cadera","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie, frente a una pared o al respaldo de una silla, con las dos manos apoyadas.\nMovimiento: Dobla una rodilla llevando el talón hacia el glúteo y bájalo despacio. Repite con la misma pierna y luego cambia.\nRespiración: Suelta el aire al subir el talón, inspira al bajar.\nQué vas a sentir: El frente del muslo y la cadera moviéndose con libertad.\nAtención: Mantén el cuerpo erguido y sube solo hasta donde la rodilla se sienta cómoda.","duracao_seg":null}]},{"dia":2,"ordem":3,"ordem_circuito":7,"nome":"Balanceo lateral de pierna","descricao":"Día 2 — Movilidad suave de la cadera","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie, de costado a la pared, con una mano apoyada en ella.\nMovimiento: Lleva la pierna de afuera un poco hacia el costado y regresa cruzando apenas por delante. Movimiento suave, como un péndulo.\nRespiración: Respira con ritmo natural.\nQué vas a sentir: Los costados de la cadera soltándose.\nAtención: El tronco queda derecho; no inclines el cuerpo para subir más la pierna.","duracao_seg":null}]},{"dia":2,"ordem":4,"ordem_circuito":8,"nome":"Balanceo sentada en silla","descricao":"Día 2 — Movilidad suave de la cadera","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada en el borde de una silla firme, pies apoyados y manos sobre los muslos.\nMovimiento: Pasa el peso lentamente de un glúteo al otro, dejando que la cadera se mueva de lado a lado.\nRespiración: Inspira en el centro, suelta el aire al llevar el peso a un lado.\nQué vas a sentir: Los huesitos de apoyo del glúteo rodando sobre la silla.\nAtención: Usa una silla estable, sin ruedas.","duracao_seg":null}]},{"dia":3,"ordem":1,"ordem_circuito":9,"nome":"Mariposa acostada","descricao":"Día 3 — Abrir la cadera con calma","tipo":"permanencia","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, junta las plantas de los pies y deja que las rodillas se abran hacia los lados. Puedes poner cojines debajo de cada rodilla.\nMovimiento: Quédate en la posición y deja que la gravedad abra la cadera poco a poco, sin empujar.\nRespiración: Respira lento, imaginando que el aire llega a la cadera.\nQué vas a sentir: Una apertura suave en la ingle y la cara interna de los muslos.\nAtención: Si tira demasiado, sube los cojines o acerca menos los pies.","duracao_seg":30}]},{"dia":3,"ordem":2,"ordem_circuito":10,"nome":"Paso adelante con apoyo","descricao":"Día 3 — Abrir la cadera con calma","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie, junto al respaldo de una silla, con una mano apoyada. Da un paso largo hacia adelante.\nMovimiento: Dobla un poco la rodilla de adelante y lleva la cadera hacia el frente, sintiendo el estiramiento en la pierna de atrás. Vuelve y repite; luego cambia de pierna.\nRespiración: Suelta el aire al avanzar la cadera, inspira al volver.\nQué vas a sentir: Un estiramiento agradable en el frente de la cadera de la pierna de atrás.\nAtención: La rodilla de adelante no pasa de la punta del pie; el talón de atrás puede despegarse.","duracao_seg":null}]},{"dia":3,"ordem":3,"ordem_circuito":11,"nome":"Figura cuatro en silla","descricao":"Día 3 — Abrir la cadera con calma","tipo":"permanencia","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada en una silla, apoya el tobillo de una pierna sobre la rodilla de la otra, formando un número cuatro.\nMovimiento: Con la espalda larga, inclina el tronco apenas hacia adelante y quédate. Luego cambia de pierna.\nRespiración: Respira profundo y deja que cada exhalación afloje un poco más.\nQué vas a sentir: Un estiramiento en el glúteo de la pierna cruzada.\nAtención: Si la rodilla molesta, apoya el tobillo más abajo, sobre la espinilla.","duracao_seg":30}]},{"dia":3,"ordem":4,"ordem_circuito":12,"nome":"Apertura de rodilla acostada","descricao":"Día 3 — Abrir la cadera con calma","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas y pies apoyados.\nMovimiento: Deja caer una rodilla hacia el costado, despacio, y vuelve al centro. Repite con la misma pierna y luego cambia.\nRespiración: Suelta el aire al abrir, inspira al cerrar.\nQué vas a sentir: La cara interna del muslo estirándose y la cadera abriéndose.\nAtención: La pelvis queda quieta; abre solo hasta donde no gire.","duracao_seg":null}]},{"dia":4,"ordem":1,"ordem_circuito":13,"nome":"Rotación de pie acostada","descricao":"Día 4 — Rotaciones sin prisa","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, piernas estiradas y relajadas, un poco separadas.\nMovimiento: Gira las dos piernas desde la cadera, llevando las puntas de los pies hacia afuera y luego hacia adentro, como limpiaparabrisas.\nRespiración: Respira libre y tranquila.\nQué vas a sentir: La cadera girando desde adentro, sin esfuerzo.\nAtención: Si la espalda se tensiona, dobla un poco las rodillas con un cojín debajo.","duracao_seg":null}]},{"dia":4,"ordem":2,"ordem_circuito":14,"nome":"Rotación sentada en silla","descricao":"Día 4 — Rotaciones sin prisa","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada en una silla, pies apoyados y rodillas a 90 grados.\nMovimiento: Sin mover la rodilla de lugar, lleva el pie hacia afuera y luego hacia adentro, deslizándolo en el suelo. Luego cambia de pierna.\nRespiración: Respira con calma durante todo el movimiento.\nQué vas a sentir: La cadera rotando mientras la rodilla queda quieta.\nAtención: Movimiento pequeño y lento; si la rodilla molesta, reduce el recorrido.","duracao_seg":null}]},{"dia":4,"ordem":3,"ordem_circuito":15,"nome":"Almeja de costado","descricao":"Día 4 — Rotaciones sin prisa","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada de lado, cabeza sobre el brazo o un cojín, rodillas dobladas y pies juntos.\nMovimiento: Manteniendo los pies juntos, abre la rodilla de arriba como una almeja y ciérrala despacio. Luego cambia de lado.\nRespiración: Suelta el aire al abrir, inspira al cerrar.\nQué vas a sentir: Un trabajo suave en el costado del glúteo.\nAtención: La cadera no rueda hacia atrás; abre menos si hace falta.","duracao_seg":null}]},{"dia":4,"ordem":4,"ordem_circuito":16,"nome":"Giro suave acostada","descricao":"Día 4 — Rotaciones sin prisa","tipo":"permanencia","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas y brazos abiertos en cruz.\nMovimiento: Deja caer las dos rodillas hacia un lado y quédate, con los hombros apoyados. Vuelve al centro y cambia de lado.\nRespiración: Respira hondo, llevando el aire hacia el costado que se estira.\nQué vas a sentir: Un estiramiento largo en la cadera y el costado del cuerpo.\nAtención: Pon un cojín bajo las rodillas si no llegan al suelo; nada debe doler.","duracao_seg":30}]},{"dia":5,"ordem":1,"ordem_circuito":17,"nome":"Puente pequeño","descricao":"Día 5 — Despertar los glúteos","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas, pies apoyados al ancho de la cadera y brazos al costado.\nMovimiento: Aprieta suavemente los glúteos y despega la cadera unos centímetros del suelo. Baja despacio.\nRespiración: Suelta el aire al subir, inspira al bajar.\nQué vas a sentir: Los glúteos y la parte de atrás de los muslos trabajando.\nAtención: Sube poco, sin arquear la espalda; si molesta la lumbar, reduce la altura.","duracao_seg":null}]},{"dia":5,"ordem":2,"ordem_circuito":18,"nome":"Pierna atrás en la pared","descricao":"Día 5 — Despertar los glúteos","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie, frente a la pared, con las dos manos apoyadas en ella.\nMovimiento: Lleva una pierna estirada un poco hacia atrás, apretando el glúteo, y vuelve. Repite y luego cambia de pierna.\nRespiración: Suelta el aire al llevar la pierna atrás.\nQué vas a sentir: El glúteo de la pierna que se mueve activándose.\nAtención: Movimiento corto; la espalda no se arquea.","duracao_seg":null}]},{"dia":5,"ordem":3,"ordem_circuito":19,"nome":"Pierna al costado acostada","descricao":"Día 5 — Despertar los glúteos","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada de lado, la pierna de abajo doblada y la de arriba estirada.\nMovimiento: Sube la pierna de arriba un palmo y bájala despacio, sin apoyarla del todo. Luego cambia de lado.\nRespiración: Suelta el aire al subir, inspira al bajar.\nQué vas a sentir: El costado de la cadera trabajando.\nAtención: La punta del pie mira hacia adelante; sube solo hasta donde puedas sin girar el cuerpo.","duracao_seg":null}]},{"dia":5,"ordem":4,"ordem_circuito":20,"nome":"Rodillas que aprietan cojín","descricao":"Día 5 — Despertar los glúteos","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada en una silla con un cojín entre las rodillas.\nMovimiento: Aprieta el cojín con las rodillas durante dos o tres segundos y suelta por completo. Repite.\nRespiración: Suelta el aire al apretar, inspira al soltar.\nQué vas a sentir: La cara interna de los muslos activándose.\nAtención: Aprieta con fuerza moderada, nunca al máximo.","duracao_seg":null}]},{"dia":6,"ordem":1,"ordem_circuito":21,"nome":"Sentarse y pararse","descricao":"Día 6 — Apoyo y estabilidad","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada en el borde de una silla firme, pies apoyados al ancho de la cadera.\nMovimiento: Inclina el tronco hacia adelante y ponte de pie empujando el suelo con los pies. Vuelve a sentarte despacio, controlando la bajada.\nRespiración: Suelta el aire al subir, inspira al bajar.\nQué vas a sentir: Glúteos y muslos trabajando juntos.\nAtención: Puedes ayudarte con las manos en los muslos; las rodillas siguen la línea de los pies.","duracao_seg":null}]},{"dia":6,"ordem":2,"ordem_circuito":22,"nome":"Peso de un pie al otro","descricao":"Día 6 — Apoyo y estabilidad","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie, pies separados al ancho de la cadera, con una silla cerca para apoyarte.\nMovimiento: Pasa el peso lentamente a un pie hasta que el otro quede liviano, y luego al otro lado.\nRespiración: Respira con calma y ritmo.\nQué vas a sentir: La cadera de apoyo sosteniendo el cuerpo con firmeza.\nAtención: Si pierdes el equilibrio, apoya la mano en la silla.","duracao_seg":null}]},{"dia":6,"ordem":3,"ordem_circuito":23,"nome":"Marcha lenta con apoyo","descricao":"Día 6 — Apoyo y estabilidad","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie, junto a una pared o silla, con una mano apoyada.\nMovimiento: Sube una rodilla hacia adelante, bájala y sube la otra, como una marcha muy lenta.\nRespiración: Respira libre, sin retener el aire.\nQué vas a sentir: La cadera moviéndose y el cuerpo buscando equilibrio.\nAtención: Sube la rodilla solo hasta donde sea cómodo; el tronco queda erguido.","duracao_seg":null}]},{"dia":6,"ordem":4,"ordem_circuito":24,"nome":"Paso lateral corto","descricao":"Día 6 — Apoyo y estabilidad","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie, rodillas un poco sueltas, manos en la cintura.\nMovimiento: Da un paso corto hacia el costado, junta los pies y da otro paso de vuelta. Ritmo tranquilo.\nRespiración: Respira con naturalidad.\nQué vas a sentir: Los costados de la cadera trabajando para sostenerte.\nAtención: Despeja el espacio alrededor para no tropezar.","duracao_seg":null}]},{"dia":7,"ordem":1,"ordem_circuito":25,"nome":"Círculos de cadera de pie","descricao":"Día 7 — Integrar y relajar","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie, pies al ancho de la cadera, rodillas sueltas y manos en la cintura.\nMovimiento: Dibuja círculos amplios y lentos con la cadera. Cambia de dirección a la mitad del tiempo.\nRespiración: Respira fluido, acompañando el círculo.\nQué vas a sentir: Toda la zona de la cadera moviéndose con soltura.\nAtención: Los círculos son del tamaño que te resulte cómodo.","duracao_seg":null}]},{"dia":7,"ordem":2,"ordem_circuito":26,"nome":"Puente con respiración","descricao":"Día 7 — Integrar y relajar","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas y pies apoyados.\nMovimiento: Sube la cadera despacio mientras sueltas el aire y bájala vértebra por vértebra mientras inspiras.\nRespiración: Exhalación larga al subir, inspiración tranquila al bajar.\nQué vas a sentir: Glúteos activos y la espalda acompañando el movimiento.\nAtención: Sube solo hasta donde la espalda se sienta cómoda.","duracao_seg":null}]},{"dia":7,"ordem":3,"ordem_circuito":27,"nome":"Estiramiento figura cuatro","descricao":"Día 7 — Integrar y relajar","tipo":"permanencia","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas. Cruza el tobillo de una pierna sobre la rodilla de la otra.\nMovimiento: Quédate así o, si quieres más, acerca con suavidad la pierna de apoyo hacia el pecho. Luego cambia de lado.\nRespiración: Respira lento y profundo.\nQué vas a sentir: Un estiramiento en el glúteo de la pierna cruzada.\nAtención: Sin tirones; si molesta la rodilla, deja la pierna de apoyo en el suelo.","duracao_seg":30}]},{"dia":7,"ordem":4,"ordem_circuito":28,"nome":"Relajación final de cadera","descricao":"Día 7 — Integrar y relajar","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, piernas estiradas o con un cojín debajo de las rodillas.\nMovimiento: Recorre con la atención tu cadera, glúteos y piernas, y en cada exhalación imagina que se aflojan un poco más.\nRespiración: Respiración lenta, soltando el aire más largo de lo que entra.\nQué vas a sentir: Las piernas pesadas y la cadera liviana y descansada.\nAtención: Levántate despacio, primero girando de lado.","duracao_seg":null}]}],"alongamentos":[{"ordem":1,"nome":"Balanceo de pelvis sentada","descricao":"Sentada en el borde de una silla, inclina la pelvis hacia adelante y hacia atrás, despacio. Un movimiento pequeño que despierta la zona.","lados":1},{"ordem":2,"nome":"Círculos de cadera de pie","descricao":"De pie, manos en la cintura y rodillas sueltas. Dibuja círculos lentos con la cadera, cambiando de dirección a la mitad.","lados":1},{"ordem":3,"nome":"Péndulo de pierna","descricao":"De pie, apoyada con una mano en la pared, balancea una pierna hacia adelante y hacia atrás sin forzar. Luego cambia de lado.","lados":2},{"ordem":4,"nome":"Rodilla al pecho acostada","descricao":"Acostada boca arriba, abraza una rodilla hacia el pecho y respira tranquila. La otra pierna queda doblada con el pie apoyado.","lados":2},{"ordem":5,"nome":"Mariposa suave","descricao":"Sentada en el suelo o en la cama, junta las plantas de los pies y deja que las rodillas caigan hacia los lados. Mueve las rodillas suavemente, como alas.","lados":1},{"ordem":6,"nome":"Limpiaparabrisas de rodillas","descricao":"Acostada boca arriba, rodillas dobladas y pies separados. Deja caer las dos rodillas hacia un lado y luego hacia el otro, sin prisa.","lados":1}]},{"circuito":"lumbar","exercicios":[{"dia":1,"ordem":1,"ordem_circuito":1,"nome":"Respiración de tres tiempos","descricao":"Día 1 — Respirar y soltar la espalda baja","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas y pies apoyados. Una mano en el vientre y otra en el pecho.\nMovimiento: Deja que el aire llene primero el vientre, después las costillas y al final el pecho. Suelta en el orden inverso, despacio.\nRespiración: Inspira en 4 tiempos y suelta en 6, sin retener el aire.\nQué vas a sentir: La espalda baja apoyándose más en el suelo con cada exhalación.\nAtención: Si sientes mareo, vuelve a respirar normal unos instantes.","duracao_seg":null}]},{"dia":1,"ordem":2,"ordem_circuito":2,"nome":"Descanso en la silla","descricao":"Día 1 — Respirar y soltar la espalda baja","tipo":"permanencia","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba con las pantorrillas apoyadas sobre el asiento de una silla o sofá, rodillas en ángulo recto.\nMovimiento: No hay movimiento. Deja que la espalda baja descanse y que el peso del cuerpo se hunda.\nRespiración: Respiración lenta y natural.\nQué vas a sentir: La zona lumbar aflojándose poco a poco.\nAtención: Si sientes hormigueo en las piernas, acomoda la posición.","duracao_seg":40}]},{"dia":1,"ordem":3,"ordem_circuito":3,"nome":"Balanceo pequeño de pelvis","descricao":"Día 1 — Respirar y soltar la espalda baja","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas y pies al ancho de la cadera.\nMovimiento: Inclina la pelvis levemente hacia atrás, acercando la lumbar al suelo, y vuelve despacio. Un movimiento casi invisible.\nRespiración: Suelta el aire al acercar la lumbar, inspira al volver.\nQué vas a sentir: La espalda baja tocando y despegándose del suelo con suavidad.\nAtención: No presiones la lumbar contra el suelo; es un vaivén, no un empuje.","duracao_seg":null}]},{"dia":1,"ordem":4,"ordem_circuito":4,"nome":"Abrazo de rodillas","descricao":"Día 1 — Respirar y soltar la espalda baja","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba. Lleva una rodilla y después la otra hacia el pecho y rodéalas con las manos.\nMovimiento: Acerca las rodillas al pecho con suavidad y afloja un poco, en un vaivén lento.\nRespiración: Suelta el aire al acercar, inspira al aflojar.\nQué vas a sentir: Un estiramiento agradable en la espalda baja y los glúteos.\nAtención: Si el cuello se tensa, apoya la cabeza en un cojín bajo.","duracao_seg":null}]},{"dia":2,"ordem":1,"ordem_circuito":5,"nome":"Báscula de pelvis sentada","descricao":"Día 2 — Pelvis que se mueve","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada en el borde de una silla firme, pies apoyados y manos en los muslos.\nMovimiento: Rueda la pelvis hacia atrás, redondeando un poco la espalda baja, y luego hacia adelante, alargándola. Despacio.\nRespiración: Suelta el aire al redondear, inspira al alargar.\nQué vas a sentir: La base de la columna moviéndose con libertad.\nAtención: Mueve dentro de un rango cómodo, sin llegar a los extremos.","duracao_seg":null}]},{"dia":2,"ordem":2,"ordem_circuito":6,"nome":"Péndulo de rodillas acostada","descricao":"Día 2 — Pelvis que se mueve","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas y juntas, brazos abiertos.\nMovimiento: Lleva las rodillas unos centímetros hacia un lado y vuelve al centro; luego hacia el otro lado.\nRespiración: Suelta el aire al ir al lado, inspira al volver.\nQué vas a sentir: Un giro suave en la espalda baja, como un masaje.\nAtención: Los hombros quedan en el suelo; si hay dolor punzante, reduce el recorrido o detente.","duracao_seg":null}]},{"dia":2,"ordem":3,"ordem_circuito":7,"nome":"Círculos de pelvis sentada","descricao":"Día 2 — Pelvis que se mueve","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada en una silla firme, pies apoyados y espalda larga.\nMovimiento: Dibuja círculos pequeños con la pelvis sobre el asiento, como si movieras un plato. Cambia de dirección a la mitad.\nRespiración: Respira libre y fluida.\nQué vas a sentir: La zona lumbar moviéndose en todas las direcciones.\nAtención: Círculos pequeños; usa una silla sin ruedas.","duracao_seg":null}]},{"dia":2,"ordem":4,"ordem_circuito":8,"nome":"Pierna que se desliza","descricao":"Día 2 — Pelvis que se mueve","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas y pies apoyados.\nMovimiento: Desliza un talón por el suelo hasta estirar la pierna y vuelve, manteniendo la espalda tranquila. Luego cambia de pierna.\nRespiración: Suelta el aire al estirar, inspira al volver.\nQué vas a sentir: La pelvis estable mientras la pierna se mueve.\nAtención: Si la espalda se arquea, estira la pierna solo hasta la mitad.","duracao_seg":null}]},{"dia":3,"ordem":1,"ordem_circuito":9,"nome":"Gato y vaca con cojín","descricao":"Día 3 — Columna viva","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: En cuatro apoyos, con un cojín doblado bajo las rodillas. Manos debajo de los hombros y rodillas debajo de la cadera.\nMovimiento: Redondea la espalda llevando el ombligo hacia arriba y luego deja que el vientre baje un poco, mirando al frente. Despacio.\nRespiración: Suelta el aire al redondear, inspira al bajar el vientre.\nQué vas a sentir: Toda la columna moviéndose como una ola.\nAtención: Si las rodillas o las muñecas molestan, hazlo sentada en una silla.","duracao_seg":null}]},{"dia":3,"ordem":2,"ordem_circuito":10,"nome":"Giro sentada en silla","descricao":"Día 3 — Columna viva","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada en una silla, pies apoyados, brazos cruzados sobre el pecho.\nMovimiento: Gira el tronco suavemente hacia un lado, vuelve al centro y gira hacia el otro. La cadera queda quieta.\nRespiración: Suelta el aire al girar, inspira en el centro.\nQué vas a sentir: La columna rotando con suavidad desde la cintura hacia arriba.\nAtención: Gira solo hasta donde sea cómodo, sin impulso.","duracao_seg":null}]},{"dia":3,"ordem":3,"ordem_circuito":11,"nome":"Inclinación lateral de pie","descricao":"Día 3 — Columna viva","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie, pies al ancho de la cadera, rodillas sueltas y brazos a los lados.\nMovimiento: Desliza una mano por el costado del muslo inclinándote apenas y vuelve al centro. Alterna los lados.\nRespiración: Suelta el aire al inclinarte, inspira al subir.\nQué vas a sentir: El costado del cuerpo estirándose y la cintura aflojando.\nAtención: No te inclines hacia adelante; el movimiento es solo lateral.","duracao_seg":null}]},{"dia":3,"ordem":4,"ordem_circuito":12,"nome":"Postura del niño con cojines","descricao":"Día 3 — Columna viva","tipo":"permanencia","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Arrodillada sobre un cojín, rodillas separadas, con varios cojines o almohadas delante.\nMovimiento: Lleva la cadera hacia los talones y apoya el pecho sobre los cojines, con los brazos relajados. Quédate ahí.\nRespiración: Respira hacia la espalda, sintiendo cómo se expande.\nQué vas a sentir: La espalda baja alargándose y descansando.\nAtención: Si las rodillas molestan, hazlo sentada inclinándote sobre una mesa con cojines.","duracao_seg":30}]},{"dia":4,"ordem":1,"ordem_circuito":13,"nome":"Estiramiento de glúteo acostada","descricao":"Día 4 — Estirar sin forzar","tipo":"permanencia","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas. Cruza el tobillo de una pierna sobre la rodilla de la otra.\nMovimiento: Quédate así o acerca suavemente la pierna de apoyo hacia ti. Luego cambia de lado.\nRespiración: Respira lento, soltando la tensión en cada exhalación.\nQué vas a sentir: Un estiramiento en el glúteo, que alivia la sensación de carga en la espalda baja.\nAtención: Sin tirones; si molesta la rodilla, deja el pie de apoyo en el suelo.","duracao_seg":30}]},{"dia":4,"ordem":2,"ordem_circuito":14,"nome":"Pierna estirada con toalla","descricao":"Día 4 — Estirar sin forzar","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, una pierna doblada con el pie apoyado. Pasa una toalla por la planta del otro pie.\nMovimiento: Sube la pierna con la toalla hasta sentir un estiramiento suave detrás del muslo y bájala despacio. Luego cambia de pierna.\nRespiración: Suelta el aire al subir, inspira al bajar.\nQué vas a sentir: La parte de atrás del muslo estirándose, con la espalda apoyada.\nAtención: La rodilla puede quedar un poco doblada; nunca fuerces el estiramiento.","duracao_seg":null}]},{"dia":4,"ordem":3,"ordem_circuito":15,"nome":"Paso adelante con apoyo","descricao":"Día 4 — Estirar sin forzar","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie, junto al respaldo de una silla, con una mano apoyada. Da un paso largo hacia adelante.\nMovimiento: Dobla un poco la rodilla de adelante y lleva la cadera al frente, sin arquear la espalda. Vuelve y repite; luego cambia.\nRespiración: Suelta el aire al avanzar, inspira al volver.\nQué vas a sentir: El frente de la cadera de la pierna de atrás estirándose.\nAtención: Mantén el ombligo suavemente hacia adentro para no arquear la lumbar.","duracao_seg":null}]},{"dia":4,"ordem":4,"ordem_circuito":16,"nome":"Giro acostada con brazos abiertos","descricao":"Día 4 — Estirar sin forzar","tipo":"permanencia","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas y brazos abiertos en cruz.\nMovimiento: Deja caer las rodillas hacia un lado y quédate. Vuelve al centro despacio y cambia de lado.\nRespiración: Respiración profunda hacia el costado que se estira.\nQué vas a sentir: Un estiramiento largo desde la cadera hasta las costillas.\nAtención: Pon un cojín bajo las rodillas si no llegan al suelo.","duracao_seg":30}]},{"dia":5,"ordem":1,"ordem_circuito":17,"nome":"Ombligo hacia adentro","descricao":"Día 5 — Centro que sostiene","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas y manos sobre el vientre.\nMovimiento: Al soltar el aire, lleva suavemente el ombligo hacia la columna, sin mover la pelvis. Sostén dos segundos y suelta.\nRespiración: Exhalación larga al activar, inspiración tranquila al soltar.\nQué vas a sentir: Un abrazo suave alrededor de la cintura.\nAtención: Es una activación ligera; no contengas el aire.","duracao_seg":null}]},{"dia":5,"ordem":2,"ordem_circuito":18,"nome":"Puente pequeño","descricao":"Día 5 — Centro que sostiene","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas y pies apoyados al ancho de la cadera.\nMovimiento: Aprieta los glúteos y despega la cadera unos centímetros del suelo. Baja despacio.\nRespiración: Suelta el aire al subir, inspira al bajar.\nQué vas a sentir: Glúteos trabajando y la espalda baja acompañando sin esfuerzo.\nAtención: Sube poco y sin arquear; si molesta la lumbar, baja la altura.","duracao_seg":null}]},{"dia":5,"ordem":3,"ordem_circuito":19,"nome":"Talón que toca el suelo","descricao":"Día 5 — Centro que sostiene","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas y pies apoyados. Levanta una pierna con la rodilla doblada en ángulo recto.\nMovimiento: Baja despacio ese talón hasta tocar el suelo y vuelve a subirlo, con el ombligo suavemente hacia adentro. Luego cambia de pierna.\nRespiración: Suelta el aire al bajar el talón, inspira al subir.\nQué vas a sentir: El centro del cuerpo trabajando para mantener la espalda quieta.\nAtención: Si la lumbar se despega del suelo, baja el talón menos.","duracao_seg":null}]},{"dia":5,"ordem":4,"ordem_circuito":20,"nome":"Brazo y pierna contrarios","descricao":"Día 5 — Centro que sostiene","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: En cuatro apoyos con un cojín bajo las rodillas, o de pie con las manos en la pared.\nMovimiento: Desliza una pierna hacia atrás por el suelo y, si te sientes estable, estira también el brazo contrario hacia adelante. Vuelve y cambia de lado.\nRespiración: Suelta el aire al estirar, inspira al volver.\nQué vas a sentir: La espalda estable y el cuerpo trabajando en diagonal.\nAtención: La cadera no gira; empieza solo con la pierna si te cuesta el equilibrio.","duracao_seg":null}]},{"dia":6,"ordem":1,"ordem_circuito":21,"nome":"Bisagra de cadera con palo","descricao":"Día 6 — Moverse con confianza","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie, pies al ancho de la cadera, rodillas sueltas. Sostén una toalla enrollada o un palo de escoba a lo largo de la espalda.\nMovimiento: Lleva la cadera hacia atrás inclinando el tronco con la espalda recta, como para cerrar un cajón con el glúteo. Vuelve a subir apretando los glúteos.\nRespiración: Inspira al bajar, suelta el aire al subir.\nQué vas a sentir: El movimiento naciendo en la cadera, no en la espalda.\nAtención: Baja poco; la espalda se mantiene larga todo el tiempo.","duracao_seg":null}]},{"dia":6,"ordem":2,"ordem_circuito":22,"nome":"Sentarse y pararse","descricao":"Día 6 — Moverse con confianza","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada en el borde de una silla firme, pies apoyados.\nMovimiento: Inclina el tronco hacia adelante con la espalda larga y ponte de pie empujando el suelo. Siéntate despacio.\nRespiración: Suelta el aire al subir, inspira al bajar.\nQué vas a sentir: Piernas y glúteos haciendo el trabajo, la espalda acompañando.\nAtención: Ayúdate con las manos en los muslos si lo necesitas.","duracao_seg":null}]},{"dia":6,"ordem":3,"ordem_circuito":23,"nome":"Espalda contra la pared","descricao":"Día 6 — Moverse con confianza","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie, de espaldas a la pared, talones a un palmo de ella, rodillas sueltas.\nMovimiento: Acerca suavemente la espalda baja a la pared y vuelve a soltar, en un vaivén lento de la pelvis.\nRespiración: Suelta el aire al acercar, inspira al soltar.\nQué vas a sentir: La pelvis encontrando una posición cómoda de pie.\nAtención: Movimiento pequeño, sin empujar con fuerza.","duracao_seg":null}]},{"dia":6,"ordem":4,"ordem_circuito":24,"nome":"Caminata con brazos sueltos","descricao":"Día 6 — Moverse con confianza","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie en un espacio despejado de tu casa.\nMovimiento: Camina despacio dejando que los brazos se balanceen y que la cintura gire un poco con cada paso.\nRespiración: Respira con ritmo natural.\nQué vas a sentir: La espalda moviéndose con soltura al caminar.\nAtención: Usa calzado cómodo y un piso sin obstáculos.","duracao_seg":null}]},{"dia":7,"ordem":1,"ordem_circuito":25,"nome":"Ola de columna sentada","descricao":"Día 7 — Integrar y relajar","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada en una silla firme, pies apoyados y manos en los muslos.\nMovimiento: Redondea la espalda desde la pelvis hacia arriba y luego alárgala desde la pelvis hasta la cabeza, como una ola.\nRespiración: Suelta el aire al redondear, inspira al alargar.\nQué vas a sentir: Cada parte de la columna moviéndose por turno.\nAtención: Ritmo lento y rango cómodo.","duracao_seg":null}]},{"dia":7,"ordem":2,"ordem_circuito":26,"nome":"Puente vértebra a vértebra","descricao":"Día 7 — Integrar y relajar","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas y pies apoyados.\nMovimiento: Sube la cadera despegando la espalda poco a poco y bájala apoyando una vértebra a la vez.\nRespiración: Suelta el aire al subir, inspira al bajar.\nQué vas a sentir: La columna desenrollándose con suavidad.\nAtención: Sube solo hasta donde la espalda se sienta cómoda.","duracao_seg":null}]},{"dia":7,"ordem":3,"ordem_circuito":27,"nome":"Giro suave de rodillas","descricao":"Día 7 — Integrar y relajar","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba, rodillas dobladas y brazos abiertos.\nMovimiento: Lleva las rodillas lentamente de un lado al otro, quedándote una respiración en cada lado.\nRespiración: Una respiración completa en cada lado.\nQué vas a sentir: La espalda baja aflojándose en cada giro.\nAtención: Recorrido cómodo; los hombros se quedan apoyados.","duracao_seg":null}]},{"dia":7,"ordem":4,"ordem_circuito":28,"nome":"Relajación de espalda baja","descricao":"Día 7 — Integrar y relajar","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Acostada boca arriba con las pantorrillas sobre una silla o un cojín bajo las rodillas.\nMovimiento: Cierra los ojos y recorre con la atención la espalda, imaginando que se ensancha y se apoya más con cada exhalación.\nRespiración: Exhalación más larga que la inspiración.\nQué vas a sentir: Una sensación de liviandad y descanso en la espalda baja.\nAtención: Para levantarte, gira primero de lado y apóyate con las manos.","duracao_seg":null}]}],"alongamentos":[{"ordem":1,"nome":"Respiración al vientre","descricao":"Acostada boca arriba con las rodillas dobladas, lleva el aire hacia el vientre y suéltalo largo. Deja que la espalda baja se apoye cada vez más.","lados":1},{"ordem":2,"nome":"Báscula de pelvis acostada","descricao":"Acostada con rodillas dobladas, inclina la pelvis apenas hacia atrás y hacia adelante. Un vaivén pequeño y suave.","lados":1},{"ordem":3,"nome":"Rodilla al pecho","descricao":"Abraza una rodilla hacia el pecho mientras la otra pierna queda doblada con el pie apoyado. Respira tranquila y luego cambia de lado.","lados":2},{"ordem":4,"nome":"Rodillas de lado a lado","descricao":"Acostada, rodillas dobladas y juntas. Déjalas caer suavemente hacia un lado y luego hacia el otro, sin prisa.","lados":1},{"ordem":5,"nome":"Gato y vaca en silla","descricao":"Sentada en una silla, manos en los muslos, redondea la espalda al soltar el aire y alárgala al inspirar. Movimiento lento y cómodo.","lados":1},{"ordem":6,"nome":"Inclinación lateral sentada","descricao":"Sentada, sube un brazo y inclínate apenas hacia el lado contrario, sintiendo el costado largo. Luego cambia de lado.","lados":2}]},{"circuito":"manos","exercicios":[{"dia":1,"ordem":1,"ordem_circuito":1,"nome":"Manos en agua tibia","descricao":"Día 1 — Calentar y soltar las manos","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada frente a una mesa con un recipiente de agua tibia, o simplemente con las manos sobre los muslos.\nMovimiento: Abre y cierra las manos despacio dentro del agua (o en el aire), moviendo todos los dedos a la vez.\nRespiración: Respira tranquila, soltando el aire largo.\nQué vas a sentir: Calor y más facilidad para mover los dedos.\nAtención: El agua debe estar tibia y agradable, nunca caliente.","duracao_seg":null}]},{"dia":1,"ordem":2,"ordem_circuito":2,"nome":"Masaje de palma","descricao":"Día 1 — Calentar y soltar las manos","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada cómoda, con una mano apoyada en el muslo con la palma hacia arriba.\nMovimiento: Con el pulgar de la otra mano haz círculos pequeños por toda la palma y la base de los dedos. Luego cambia de mano.\nRespiración: Respira lento y deja que los hombros bajen.\nQué vas a sentir: La palma aflojándose y más calor en la mano.\nAtención: Presión suave y agradable; evita puntos que duelan.","duracao_seg":null}]},{"dia":1,"ordem":3,"ordem_circuito":3,"nome":"Dedo por dedo","descricao":"Día 1 — Calentar y soltar las manos","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada, una mano relajada frente a ti.\nMovimiento: Con la otra mano toma cada dedo desde la base y deslízate hacia la punta, como si lo peinaras. Recorre los cinco dedos y cambia de mano.\nRespiración: Respira con calma durante todo el recorrido.\nQué vas a sentir: Cada dedo más despierto y liviano.\nAtención: No tires de los dedos ni los hagas crujir.","duracao_seg":null}]},{"dia":1,"ordem":4,"ordem_circuito":4,"nome":"Puño suave y estrella","descricao":"Día 1 — Calentar y soltar las manos","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada, antebrazos apoyados sobre una mesa y palmas hacia arriba.\nMovimiento: Cierra las manos en un puño suave y ábrelas estirando los dedos bien separados, como una estrella.\nRespiración: Suelta el aire al abrir, inspira al cerrar.\nQué vas a sentir: Las manos moviéndose con más soltura en cada repetición.\nAtención: El puño es suave; no aprietes con fuerza.","duracao_seg":null}]},{"dia":2,"ordem":1,"ordem_circuito":5,"nome":"Muñeca arriba y abajo","descricao":"Día 2 — Muñecas en movimiento","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada, antebrazos apoyados en la mesa con las manos fuera del borde, palmas hacia abajo.\nMovimiento: Sube las manos doblando la muñeca y bájalas despacio, como si saludaras.\nRespiración: Respira con ritmo natural.\nQué vas a sentir: La muñeca moviéndose con suavidad en toda su amplitud cómoda.\nAtención: Mueve sin dolor; si molesta, reduce el recorrido.","duracao_seg":null}]},{"dia":2,"ordem":2,"ordem_circuito":6,"nome":"Muñeca de lado a lado","descricao":"Día 2 — Muñecas en movimiento","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada, antebrazos apoyados en la mesa y palmas hacia abajo.\nMovimiento: Desliza las manos sobre la mesa hacia el lado del meñique y luego hacia el lado del pulgar, como un limpiaparabrisas.\nRespiración: Respira tranquila, sin retener el aire.\nQué vas a sentir: Los costados de la muñeca aflojándose.\nAtención: Los antebrazos quedan quietos; solo se mueve la muñeca.","duracao_seg":null}]},{"dia":2,"ordem":3,"ordem_circuito":7,"nome":"Girar las palmas","descricao":"Día 2 — Muñecas en movimiento","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada, codos pegados al cuerpo y doblados en ángulo recto, manos al frente.\nMovimiento: Gira las palmas hacia arriba y luego hacia abajo, despacio, como si dieras vuelta una tortilla.\nRespiración: Respira con calma.\nQué vas a sentir: El antebrazo y la muñeca girando con suavidad.\nAtención: Los codos no se separan del cuerpo.","duracao_seg":null}]},{"dia":2,"ordem":4,"ordem_circuito":8,"nome":"Manos en oración","descricao":"Día 2 — Muñecas en movimiento","tipo":"permanencia","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada o de pie, junta las palmas frente al pecho, con los codos abiertos.\nMovimiento: Baja lentamente las manos juntas hacia la cintura hasta sentir un estiramiento suave en las muñecas, y quédate.\nRespiración: Respira lento y profundo.\nQué vas a sentir: Un estiramiento agradable en la cara interna de las muñecas.\nAtención: Quédate donde se sienta cómodo; si hay hormigueo, afloja.","duracao_seg":30}]},{"dia":3,"ordem":1,"ordem_circuito":9,"nome":"Pulgar toca cada dedo","descricao":"Día 3 — Dedos ágiles","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada, manos frente a ti con las palmas hacia arriba.\nMovimiento: Toca con la yema del pulgar la yema de cada dedo, del índice al meñique, y vuelve. Haz las dos manos a la vez.\nRespiración: Respira libre.\nQué vas a sentir: Los dedos moviéndose con precisión y soltura.\nAtención: Toque suave, sin apretar las yemas.","duracao_seg":null}]},{"dia":3,"ordem":2,"ordem_circuito":10,"nome":"Dedos que caminan","descricao":"Día 3 — Dedos ágiles","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada frente a una mesa, manos apoyadas con las palmas hacia abajo.\nMovimiento: Haz caminar los dedos hacia adelante sobre la mesa, como una araña, y luego hacia atrás.\nRespiración: Respira con ritmo tranquilo.\nQué vas a sentir: Cada dedo trabajando por separado.\nAtención: Mantén los hombros relajados mientras mueves los dedos.","duracao_seg":null}]},{"dia":3,"ordem":3,"ordem_circuito":11,"nome":"Garra suave","descricao":"Día 3 — Dedos ágiles","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada, manos al frente con los dedos estirados.\nMovimiento: Dobla solo las dos últimas articulaciones de los dedos, formando una garra, y vuelve a estirar.\nRespiración: Suelta el aire al doblar, inspira al estirar.\nQué vas a sentir: Las pequeñas articulaciones de los dedos moviéndose.\nAtención: Movimiento suave; si alguna articulación molesta, dóblala menos.","duracao_seg":null}]},{"dia":3,"ordem":4,"ordem_circuito":12,"nome":"Abanico de dedos","descricao":"Día 3 — Dedos ágiles","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada, manos apoyadas sobre la mesa con las palmas hacia abajo.\nMovimiento: Separa los dedos lo más que puedas sin dolor, como un abanico, y vuelve a juntarlos.\nRespiración: Suelta el aire al separar, inspira al juntar.\nQué vas a sentir: El espacio entre los dedos abriéndose.\nAtención: Sin forzar; abre solo hasta donde sea cómodo.","duracao_seg":null}]},{"dia":4,"ordem":1,"ordem_circuito":13,"nome":"Estiramiento de palma en mesa","descricao":"Día 4 — Estirar con suavidad","tipo":"permanencia","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie frente a una mesa, apoya una palma con los dedos apuntando hacia ti.\nMovimiento: Inclina el cuerpo apenas hacia atrás hasta sentir un estiramiento suave en el antebrazo y quédate. Luego cambia de mano.\nRespiración: Respira lento, aflojando en cada exhalación.\nQué vas a sentir: Un estiramiento en la palma y la cara interna del antebrazo.\nAtención: Poco peso sobre la mano; si hay dolor punzante, detente.","duracao_seg":30}]},{"dia":4,"ordem":2,"ordem_circuito":14,"nome":"Estiramiento de dedos uno a uno","descricao":"Día 4 — Estirar con suavidad","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada, una mano frente a ti con la palma hacia arriba.\nMovimiento: Con la otra mano lleva cada dedo suavemente hacia atrás, unos segundos por dedo. Luego cambia de mano.\nRespiración: Respira tranquila.\nQué vas a sentir: Un estiramiento suave en la base de cada dedo.\nAtención: Estira muy poco; nunca hasta sentir dolor.","duracao_seg":null}]},{"dia":4,"ordem":3,"ordem_circuito":15,"nome":"Pulgar hacia afuera","descricao":"Día 4 — Estirar con suavidad","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada, una mano apoyada de canto sobre la mesa, con el meñique abajo.\nMovimiento: Con la otra mano lleva el pulgar suavemente hacia afuera y hacia atrás, y suéltalo. Repite y cambia de mano.\nRespiración: Suelta el aire al estirar.\nQué vas a sentir: La base del pulgar abriéndose.\nAtención: Movimiento delicado; la base del pulgar es sensible.","duracao_seg":null}]},{"dia":4,"ordem":4,"ordem_circuito":16,"nome":"Brazos al cielo","descricao":"Día 4 — Estirar con suavidad","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada o de pie, brazos al costado del cuerpo.\nMovimiento: Sube los brazos por delante abriendo bien las manos y bájalos cerrándolas en un puño suave.\nRespiración: Inspira al subir, suelta el aire al bajar.\nQué vas a sentir: Brazos, muñecas y dedos estirándose juntos.\nAtención: Sube los brazos solo hasta donde los hombros estén cómodos.","duracao_seg":null}]},{"dia":5,"ordem":1,"ordem_circuito":17,"nome":"Apretar la toalla","descricao":"Día 5 — Agarre suave","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada, con una toalla pequeña enrollada en una mano.\nMovimiento: Aprieta la toalla con fuerza moderada durante dos o tres segundos y suelta por completo. Luego cambia de mano.\nRespiración: Suelta el aire al apretar, inspira al soltar.\nQué vas a sentir: La mano y el antebrazo activándose.\nAtención: Fuerza moderada, nunca al máximo.","duracao_seg":null}]},{"dia":5,"ordem":2,"ordem_circuito":18,"nome":"Escurrir la toalla","descricao":"Día 5 — Agarre suave","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada, sostén una toalla enrollada con las dos manos, una junto a la otra.\nMovimiento: Gira las manos en direcciones contrarias como si escurrieras la toalla, despacio. Luego invierte el sentido.\nRespiración: Respira con ritmo natural.\nQué vas a sentir: Las muñecas y los antebrazos trabajando.\nAtención: Gira suave; si molesta la muñeca, reduce la fuerza.","duracao_seg":null}]},{"dia":5,"ordem":3,"ordem_circuito":19,"nome":"Pinza con los dedos","descricao":"Día 5 — Agarre suave","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada frente a una mesa con una esponja, un calcetín enrollado o un cojín pequeño.\nMovimiento: Aprieta el objeto entre el pulgar y los otros dedos, como una pinza, y suelta. Luego cambia de mano.\nRespiración: Suelta el aire al apretar.\nQué vas a sentir: Los dedos y la base del pulgar trabajando.\nAtención: Usa un objeto blando y aprieta con suavidad.","duracao_seg":null}]},{"dia":5,"ordem":4,"ordem_circuito":20,"nome":"Dedos que empujan","descricao":"Día 5 — Agarre suave","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada, junta las yemas de los dedos de ambas manos frente al pecho, formando una cúpula.\nMovimiento: Empuja suavemente las yemas unas contra otras, abriendo las palmas, y suelta.\nRespiración: Suelta el aire al empujar, inspira al soltar.\nQué vas a sentir: Los dedos firmes y las palmas abriéndose.\nAtención: Presión ligera; los hombros quedan relajados.","duracao_seg":null}]},{"dia":6,"ordem":1,"ordem_circuito":21,"nome":"Piano en la mesa","descricao":"Día 6 — Destreza y coordinación","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada frente a una mesa, manos apoyadas con los dedos un poco doblados.\nMovimiento: Levanta y apoya cada dedo por turno, como si tocaras el piano, del meñique al pulgar y de vuelta.\nRespiración: Respira tranquila y con ritmo.\nQué vas a sentir: Cada dedo moviéndose de forma independiente.\nAtención: Si un dedo cuesta más, no lo fuerces; acompáñalo con calma.","duracao_seg":null}]},{"dia":6,"ordem":2,"ordem_circuito":22,"nome":"Arrugar una hoja","descricao":"Día 6 — Destreza y coordinación","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada frente a una mesa, con una hoja de papel o una servilleta extendida bajo una mano.\nMovimiento: Usando solo los dedos de esa mano, arruga la hoja hasta hacer una bolita. Luego estírala y cambia de mano.\nRespiración: Respira libre.\nQué vas a sentir: Los dedos coordinándose y trabajando juntos.\nAtención: Descansa la mano si sientes cansancio.","duracao_seg":null}]},{"dia":6,"ordem":3,"ordem_circuito":23,"nome":"Recoger objetos pequeños","descricao":"Día 6 — Destreza y coordinación","tipo":"tempo","bilateral":true,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada frente a una mesa con algunos objetos pequeños, como botones, porotos o frijoles.\nMovimiento: Toma los objetos de a uno con la punta de los dedos y pásalos a un recipiente. Luego cambia de mano.\nRespiración: Respira con calma y sin prisa.\nQué vas a sentir: Precisión y control en la punta de los dedos.\nAtención: Guarda los objetos pequeños lejos de niños y mascotas.","duracao_seg":null}]},{"dia":6,"ordem":4,"ordem_circuito":24,"nome":"Ocho con las muñecas","descricao":"Día 6 — Destreza y coordinación","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada, con las manos entrelazadas frente al pecho y los codos relajados.\nMovimiento: Dibuja con las manos unidas un ocho acostado en el aire, despacio. Cambia de dirección a la mitad.\nRespiración: Respira fluido, acompañando el movimiento.\nQué vas a sentir: Las muñecas moviéndose en todas las direcciones.\nAtención: Ocho pequeño y lento, sin dolor.","duracao_seg":null}]},{"dia":7,"ordem":1,"ordem_circuito":25,"nome":"Ola de dedos","descricao":"Día 7 — Integrar y relajar","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada, manos al frente con las palmas hacia abajo.\nMovimiento: Cierra los dedos uno por uno desde el meñique hasta el pulgar y ábrelos en el mismo orden, como una ola.\nRespiración: Respira lento y tranquilo.\nQué vas a sentir: Los dedos moviéndose con fluidez.\nAtención: Ritmo lento; cierra sin apretar.","duracao_seg":null}]},{"dia":7,"ordem":2,"ordem_circuito":26,"nome":"Circuito de muñecas","descricao":"Día 7 — Integrar y relajar","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada, antebrazos apoyados sobre una mesa con las manos fuera del borde.\nMovimiento: Combina en secuencia: muñeca arriba y abajo, de lado a lado y círculos lentos, unas repeticiones de cada uno.\nRespiración: Respira con ritmo natural.\nQué vas a sentir: Las muñecas sueltas y cómodas.\nAtención: Todo dentro de un rango sin dolor.","duracao_seg":null}]},{"dia":7,"ordem":3,"ordem_circuito":27,"nome":"Palmas contra la pared","descricao":"Día 7 — Integrar y relajar","tipo":"permanencia","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: De pie frente a una pared, apoya las palmas a la altura del pecho con los dedos hacia arriba.\nMovimiento: Lleva el cuerpo apenas hacia la pared hasta sentir un estiramiento suave en las muñecas y quédate.\nRespiración: Respira profundo, aflojando en cada exhalación.\nQué vas a sentir: Las palmas y las muñecas estirándose con suavidad.\nAtención: Poco peso sobre las manos; aléjate si sientes hormigueo.","duracao_seg":30}]},{"dia":7,"ordem":4,"ordem_circuito":28,"nome":"Manos que descansan","descricao":"Día 7 — Integrar y relajar","tipo":"tempo","bilateral":false,"variacoes":[{"nivel":1,"instrucoes":"Preparación: Sentada cómoda, manos apoyadas sobre los muslos con las palmas hacia arriba.\nMovimiento: Cierra los ojos y recorre con la atención cada dedo, la palma y la muñeca, dejando que se aflojen por completo.\nRespiración: Exhalación más larga que la inspiración.\nQué vas a sentir: Las manos tibias, livianas y descansadas.\nAtención: Quédate el tiempo que necesites antes de retomar tus tareas.","duracao_seg":null}]}],"alongamentos":[{"ordem":1,"nome":"Frotar las palmas","descricao":"Frota las palmas de las manos entre sí con ritmo tranquilo hasta sentir calor. Después apóyalas unos segundos sobre los muslos.","lados":1},{"ordem":2,"nome":"Abrir y cerrar las manos","descricao":"Abre las manos estirando los dedos como una estrella y ciérralas en un puño suave. Movimiento lento y sin apretar.","lados":1},{"ordem":3,"nome":"Círculos de muñeca","descricao":"Con los codos apoyados en una mesa, dibuja círculos lentos con las muñecas. Cambia de dirección a la mitad.","lados":1},{"ordem":4,"nome":"Estiramiento de palma","descricao":"Estira un brazo al frente con la palma hacia afuera y, con la otra mano, lleva los dedos suavemente hacia ti. Luego cambia de mano.","lados":2},{"ordem":5,"nome":"Estiramiento del dorso","descricao":"Estira un brazo al frente con la palma hacia abajo y lleva suavemente el dorso de la mano hacia ti con la otra mano. Luego cambia.","lados":2},{"ordem":6,"nome":"Sacudir las manos","descricao":"Deja los brazos sueltos y sacude las manos con suavidad, como si quisieras secarlas. Suelta también los hombros.","lados":1}]}]$doc$::jsonb;
  p jsonb;
  e jsonb;
  v jsonb;
  a jsonb;
  v_ex_id uuid;
begin
  for p in select * from jsonb_array_elements(v_doc)
  loop
    for e in select * from jsonb_array_elements(p->'exercicios')
    loop
      insert into public.exercises
        (circuito, dia_do_ciclo, ordem_no_dia, ordem_no_circuito, nome, descricao, tipo, bilateral, ativo)
      values (
        p->>'circuito', (e->>'dia')::int, (e->>'ordem')::int, (e->>'ordem_circuito')::int,
        e->>'nome', e->>'descricao', e->>'tipo', (e->>'bilateral')::boolean, true
      )
      on conflict (circuito, dia_do_ciclo, ordem_no_dia) do update
        set nome = excluded.nome,
            descricao = excluded.descricao,
            ordem_no_circuito = excluded.ordem_no_circuito,
            tipo = excluded.tipo,
            bilateral = excluded.bilateral
      returning id into v_ex_id;

      for v in select * from jsonb_array_elements(e->'variacoes')
      loop
        insert into public.exercise_variations (exercise_id, nivel, instrucoes, duracao_seg)
        values (v_ex_id, (v->>'nivel')::int, v->>'instrucoes', nullif(v->>'duracao_seg', '')::int)
        on conflict (exercise_id, nivel) do update
          set instrucoes = excluded.instrucoes,
              duracao_seg = excluded.duracao_seg;
      end loop;
    end loop;

    for a in select * from jsonb_array_elements(p->'alongamentos')
    loop
      insert into public.stretches (circuito, ordem, nome, descricao, lados, duracao_seg)
      values (p->>'circuito', (a->>'ordem')::int, a->>'nome', a->>'descricao', (a->>'lados')::int, 30)
      on conflict (circuito, ordem) do update
        set nome = excluded.nome,
            descricao = excluded.descricao,
            lados = excluded.lados;
    end loop;
  end loop;
end
$conteudo$;

notify pgrst, 'reload schema';

-- ---------------------------------------------------------------------
-- VERIFICAÇÃO
-- ---------------------------------------------------------------------
select c.slug as circuito,
       c.semanas,
       (select count(*) from public.exercises e where e.circuito = c.slug) as exercicios,
       (select count(*) from public.exercise_variations ev
          join public.exercises e on e.id = ev.exercise_id where e.circuito = c.slug) as variacoes,
       (select count(*) from public.stretches s where s.circuito = c.slug) as alongamentos
  from public.circuitos c
 order by c.slug;
